/* stresstest comparison report — static UI.
 *
 * Reads window.REPORT_DATA (populated by data.js — regenerated by
 * `make stresstest`) and renders the page. Edit freely and refresh the
 * browser; no test rerun required.
 *
 * Page structure:
 *  Heatmap section: scenario rows × protocol columns colored by the
 *  p2p_normal-sweep success rate (production-shaped baseline). Clicking
 *  any cell opens a modal dialog with a tab bar to flip between sweeps;
 *  each tab shows a CDF (single-point sweep) or a P99 trend line
 *  (multi-point sweep) for the selected scenario × all protocols.
 */

'use strict';

// Protocol series colors — used for chart lines, dataset point markers,
// and the modal's per-protocol summary line. Picked with similar
// saturation/lightness so the protocols read as peers rather than
// figure/ground.
const PROTOCOL_COLORS = {
  OBFT:    '#ed8936', // light orange
  '2abOBFT': '#06b6d4', // cyan
  QBFT:    '#e85a71', // light pink-red
};

// SLOT_END_MS is the spec's relay cutoff (the 4 s proposer-duty
// deadline). Used as the right edge of the CDF x-axis so misses render as
// a visible plateau between the last sample and the deadline.
const SLOT_END_MS = 4000;

// cdfZonesPlugin paints three horizontal bands across the CDF chart area
// keyed to the cumulative-success-rate y-axis: red ≤ 90%, yellow 90–99%,
// green 99–100%. Tints are kept light (low saturation × low alpha) so
// the bands read as background, not as data. Applied only to single-
// point CDF charts (buildLatencyChart); the trend chart's y-axis is in
// milliseconds, where these thresholds don't apply.
const cdfZonesPlugin = {
  id: 'cdfZones',
  beforeDatasetsDraw(chart) {
    const { ctx, chartArea, scales } = chart;
    const y = scales.y;
    if (!y) return;
    const zones = [
      { from: 0, to: 0.9, color: 'hsla(0, 70%, 75%, 0.06)' },
      { from: 0.9, to: 0.99, color: 'hsla(50, 90%, 60%, 0.06)' },
      { from: 0.99, to: 1.0, color: 'hsla(130, 55%, 60%, 0.09)' },
    ];
    ctx.save();
    zones.forEach((z) => {
      const yTop = y.getPixelForValue(z.to);
      const yBottom = y.getPixelForValue(z.from);
      ctx.fillStyle = z.color;
      ctx.fillRect(chartArea.left, yTop, chartArea.right - chartArea.left, yBottom - yTop);
    });
    ctx.restore();
  },
};

document.addEventListener('DOMContentLoaded', main);

function main() {
  const data = window.REPORT_DATA;
  const root = document.getElementById('root');
  if (!data) {
    return; // index.html already shows the placeholder.
  }
  applyChartDefaults();
  root.innerHTML = '';
  const mainEl = h('main');
  const overview = renderHeatmap(data);
  if (overview) mainEl.appendChild(overview);
  root.appendChild(mainEl);
}

// applyChartDefaults tweaks Chart.js globally so individual chart configs
// stay short.
function applyChartDefaults() {
  if (typeof Chart === 'undefined') return;
  Chart.defaults.font.family = '-apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif';
  Chart.defaults.font.size = 12;
  Chart.defaults.color = '#475569';
  Chart.defaults.borderColor = 'rgba(15, 23, 42, 0.06)';
  Chart.defaults.elements.line.tension = 0.15;
  Chart.defaults.elements.line.borderWidth = 2.5;
  Chart.defaults.elements.point.radius = 4;
  Chart.defaults.elements.point.hoverRadius = 7;
  Chart.defaults.plugins.tooltip.padding = 10;
  Chart.defaults.plugins.tooltip.cornerRadius = 6;
  Chart.defaults.plugins.tooltip.backgroundColor = 'rgba(15, 23, 42, 0.92)';
  Chart.defaults.plugins.tooltip.titleFont = { size: 12, weight: '600' };
  Chart.defaults.plugins.tooltip.bodyFont = { size: 12 };
  Chart.defaults.plugins.tooltip.boxPadding = 6;
  Chart.defaults.plugins.legend.labels.boxWidth = 12;
  Chart.defaults.plugins.legend.labels.font = { size: 12 };
}

// ---- heatmap overview ------------------------------------------------

// renderHeatmap draws the page's only persistent section: a grid of
// scenario rows × protocol columns colored by p2p_normal-sweep success
// rate (the production-shaped baseline). Each Scenario.Group becomes its
// own card so groups read as visually distinct chunks rather than rows
// in one wall of data. Clicking a cell opens the per-scenario modal.
function renderHeatmap(data) {
  const baseline = data.sweeps.find((s) => s.name === 'p2p_normal');
  if (!baseline || baseline.points.length === 0) return null;
  const point = baseline.points[0];

  const section = h('section', { class: 'heatmap', id: 'overview' });
  // --hcols drives the shared grid template (column-header row + every
  // .hrow inside every card). Keeping one CSS var means cards always
  // align horizontally with the column-header bar.
  section.style.setProperty('--hcols', String(data.protocols.length));

  const head = h('div', { class: 'heatmap-head' });
  head.appendChild(h('h2', {}, 'Overview: success rate by scenario'));
  head.appendChild(
    h(
      'p',
      { class: 'desc' },
      `At the p2p_normal operating point (${(baseline.params || []).join(', ')}).`,
    ),
  );
  section.appendChild(head);

  // Shared column-header bar — sits above every group card. Empty
  // top-left placeholder lines up with the scenario-name column.
  const cols = h('div', { class: 'heatmap-cols' });
  cols.appendChild(h('div', { class: 'col-head scen' }));
  data.protocols.forEach((p) => cols.appendChild(h('div', { class: 'col-head' }, p)));
  section.appendChild(cols);

  // Bucket scenarios by group, preserving catalog order.
  const groups = new Map();
  const order = [];
  data.scenarios.forEach((sc) => {
    const g = sc.group || 'Other';
    if (!groups.has(g)) {
      groups.set(g, []);
      order.push(g);
    }
    groups.get(g).push(sc);
  });

  order.forEach((g) => {
    const card = h('div', { class: 'heatmap-group' });
    card.appendChild(h('h3', { class: 'heatmap-group-label' }, g));
    const rows = h('div', { class: 'heatmap-rows' });
    groups.get(g).forEach((sc) => {
      const row = h('div', { class: 'hrow', 'data-scenario': sc.name });
      row.appendChild(h('div', { class: 'hname' }, sc.title || sc.name));
      data.protocols.forEach((p) => {
        const cell = findCell(point, sc.name, p);
        row.appendChild(renderHeatmapCell(cell, sc));
      });
      rows.appendChild(row);
    });
    card.appendChild(rows);
    section.appendChild(card);
  });

  return section;
}

// rateToHue maps a success rate to a chart-friendly hue:
//   rate ≤ 80% → red (hue 0)
//   rate = 90% → yellow (hue 60)
//   rate = 100% → green (hue 120)
// Threshold pick: a stress-tier scenario decides on most iterations but
// jitter can push a few past the cutoff → 90%+ is "fine," 80–90% is
// "marginal," <80% is a real problem worth flagging.
function rateToHue(rate) {
  if (rate <= 0.8) return 0;
  if (rate >= 1.0) return 120;
  return Math.round((rate - 0.8) * 600);
}

// renderHeatmapCell colors a single cell by success rate via rateToHue.
// n/a cells (iterations=0) render grey and don't open the modal. Click
// highlights the row and opens the scenario modal.
function renderHeatmapCell(cell, scenario) {
  if (!cell || cell.iterations === 0) {
    return h(
      'div',
      {
        class: 'hcell na',
        title: `n/a — scenario doesn't apply to this protocol`,
      },
      'n/a',
    );
  }
  const rate = cell.successRate;
  const hue = rateToHue(rate);
  const pct = Math.round(rate * 100);
  const p99 = cell.decisionTime ? `${Math.round(cell.decisionTime.p99)} ms p99` : 'no decisions';
  const el = h(
    'div',
    {
      class: 'hcell',
      style: `--hue: ${hue}`,
      title: `${scenario.title || scenario.name} · ${cell.protocol}\n${pct}% success · ${p99}\nClick to drill in`,
    },
    `${pct}%`,
  );
  el.addEventListener('click', () => {
    selectHeatmapRow(el);
    openScenarioModal(scenario);
  });
  return el;
}

// selectHeatmapRow visually marks the row containing `el` as selected,
// clearing any previous selection. Provides "you're looking at this one"
// feedback that persists after the modal is dismissed.
function selectHeatmapRow(el) {
  const section = el.closest('section.heatmap');
  if (!section) return;
  section.querySelectorAll('.hrow.selected').forEach((r) => r.classList.remove('selected'));
  const row = el.closest('.hrow');
  if (row) row.classList.add('selected');
}

// ---- scenario modal --------------------------------------------------
//
// One <dialog> element is cached across opens. Each open rebuilds the
// content (cheap; ≤ 4 tabs and 1 chart). Tab clicks rebuild the content
// area in place rather than maintaining 4 hidden charts — keeps memory
// usage flat and avoids the Chart.js "hidden canvas → 0 dims" foot-gun.

// currentChart is the live Chart.js instance shown in the modal, or null
// when the modal is closed (or between renders). Tracked so we can
// destroy it before swapping tabs / closing the modal.
let currentChart = null;

function destroyCurrentChart() {
  if (currentChart) {
    currentChart.destroy();
    currentChart = null;
  }
}

function closeScenarioModal(dlg) {
  destroyCurrentChart();
  dlg.close();
}

function openScenarioModal(scenario) {
  const data = window.REPORT_DATA;
  if (!data) return;

  let dlg = document.getElementById('scenario-dialog');
  if (!dlg) {
    dlg = h('dialog', { id: 'scenario-dialog', class: 'scenario-modal' });
    document.body.appendChild(dlg);
    // Backdrop click closes (clicks inside the dialog target inner
    // elements, not dlg itself).
    dlg.addEventListener('click', (ev) => {
      if (ev.target === dlg) closeScenarioModal(dlg);
    });
    // ESC-key closes the modal natively; `cancel` fires before close.
    // We also tear down the chart on `close` so cases not covered by
    // closeScenarioModal (ESC, future programmatic closers) are safe.
    dlg.addEventListener('close', destroyCurrentChart);
    dlg.addEventListener('cancel', destroyCurrentChart);
  }
  dlg.innerHTML = '';

  // Header — scenario title + identifiers + close button.
  const head = h('header', { class: 'sm-head' });
  head.appendChild(h('h2', {}, scenario.title || scenario.name));
  const closeBtn = h('button', { type: 'button', class: 'sm-close', 'aria-label': 'Close' }, '×');
  closeBtn.addEventListener('click', () => closeScenarioModal(dlg));
  head.appendChild(closeBtn);
  dlg.appendChild(head);

  const body = h('div', { class: 'sm-body' });

  // Tab bar — one tab per sweep, in catalog order. p2p_ideal first.
  // Prefixed with a "p2p network:" label since every sweep dimension
  // (BTT, heavy-tail, loss, correlated delays) is a network-layer knob.
  const tabs = h('div', { class: 'sm-tabs', role: 'tablist' });
  tabs.appendChild(h('span', { class: 'sm-tabs-label' }, 'p2p network:'));
  data.sweeps.forEach((sw) => {
    const tab = h(
      'button',
      {
        type: 'button',
        class: 'sm-tab',
        role: 'tab',
        'data-sweep': sw.name,
      },
      sw.title || sw.name,
    );
    tab.addEventListener('click', () => selectSweepTab(dlg, scenario, sw));
    tabs.appendChild(tab);
  });
  body.appendChild(tabs);

  // Content area — swapped on every tab click.
  body.appendChild(h('div', { class: 'sm-content' }));
  dlg.appendChild(body);

  dlg.showModal();
  // Default to p2p_normal — matches what the heatmap colors are derived
  // from. Falls back to the first sweep if p2p_normal isn't present
  // (defensive against custom sweep lists).
  const defaultSweep = data.sweeps.find((s) => s.name === 'p2p_normal') || data.sweeps[0];
  selectSweepTab(dlg, scenario, defaultSweep);
}

// selectSweepTab activates the tab for `sweep` and rebuilds the content
// area: sweep description (if any), per-protocol summary, and the chart
// (CDF for single-point sweeps, P99 trend line for multi-point).
function selectSweepTab(dlg, scenario, sweep) {
  const data = window.REPORT_DATA;
  if (!data) return;

  dlg.querySelectorAll('.sm-tab').forEach((t) => {
    t.classList.toggle('active', t.getAttribute('data-sweep') === sweep.name);
  });

  const content = dlg.querySelector('.sm-content');
  if (!content) return;
  content.innerHTML = '';

  // Top strip: description on the left, per-protocol legend pinned to
  // the top-right. Legend uses `margin-left: auto` so it stays right-
  // aligned even when there's no description.
  const top = h('div', { class: 'sm-content-top' });
  if (sweep.description) {
    const desc = h('p', { class: 'desc' });
    desc.innerHTML = formatDescription(sweep.description);
    top.appendChild(desc);
  }
  top.appendChild(buildSweepLegend(sweep, scenario, data.protocols));
  content.appendChild(top);

  const wrap = h('div', { class: 'sm-chart-wrap' });
  const canvas = h('canvas');
  wrap.appendChild(canvas);
  content.appendChild(wrap);

  destroyCurrentChart();
  currentChart = buildSweepChart(canvas, sweep, scenario, data.protocols);
}

// protocolStats returns success-rate and P99 ranges for `protocol` across
// the sweep's points, or null when the scenario doesn't apply at any
// point. Used by buildSweepLegend to render the colored per-protocol
// summary rows above each chart.
function protocolStats(sweep, scenario, protocol) {
  const cells = sweep.points
    .map((pt) => findCell(pt, scenario.name, protocol))
    .filter((c) => c && c.iterations > 0);
  if (cells.length === 0) return null;
  const successes = cells.map((c) => c.successRate);
  const p99s = cells
    .map((c) => (c.decisionTime ? c.decisionTime.p99 : null))
    .filter((v) => v !== null);
  return {
    successMin: Math.min(...successes),
    successMax: Math.max(...successes),
    p99Min: p99s.length > 0 ? Math.min(...p99s) : null,
    p99Max: p99s.length > 0 ? Math.max(...p99s) : null,
  };
}

// buildSweepLegend renders one row per protocol: colored swatch + name +
// success-rate chip (hue-tinted by the worst-case rate via rateToHue,
// matching the heatmap gradient) + p99 (range when the sweep is
// multi-point). Replaces Chart.js's built-in legend, which is disabled
// in the chart options.
//
// Every row contributes exactly five children (swatch, name, chip, sep,
// p99) so the parent grid keeps columns aligned across rows; n/a rows
// emit empty placeholders for the missing sep/p99 slots.
function buildSweepLegend(sweep, scenario, protocols) {
  const legend = h('div', { class: 'sm-legend' });
  protocols.forEach((p) => {
    const row = h('div', { class: 'sm-legend-item' });
    row.appendChild(
      h('span', { class: 'sm-legend-swatch', style: `background: ${protocolColor(p)}` }),
    );
    row.appendChild(h('span', { class: 'sm-legend-name' }, p));
    const stats = protocolStats(sweep, scenario, p);
    if (!stats) {
      row.appendChild(h('span', { class: 'sm-legend-pct na' }, 'n/a'));
      row.appendChild(h('span', { class: 'sm-legend-sep' }));
      row.appendChild(h('span', { class: 'sm-legend-p99' }));
      legend.appendChild(row);
      return;
    }
    // Color the chip by the worst-case (min) rate so a sweep that dips
    // below 80% reads as red even if other points are green.
    const hue = rateToHue(stats.successMin);
    const sMin = Math.round(stats.successMin * 100);
    const sMax = Math.round(stats.successMax * 100);
    const sStr = sMin === sMax ? `${sMin}%` : `${sMin}–${sMax}%`;
    row.appendChild(
      h('span', { class: 'sm-legend-pct', style: `--hue: ${hue}` }, sStr),
    );
    if (stats.p99Min !== null) {
      const pMin = Math.round(stats.p99Min);
      const pMax = Math.round(stats.p99Max);
      const pStr = pMin === pMax ? `p99 ${pMin} ms` : `p99 ${pMin}–${pMax} ms`;
      row.appendChild(h('span', { class: 'sm-legend-sep' }, '·'));
      row.appendChild(h('span', { class: 'sm-legend-p99' }, pStr));
    } else {
      row.appendChild(h('span', { class: 'sm-legend-sep' }));
      row.appendChild(h('span', { class: 'sm-legend-p99' }));
    }
    legend.appendChild(row);
  });
  return legend;
}

// buildSweepChart returns a CDF (for a 1-point sweep) or a P99 trend
// line (for a multi-point sweep).
function buildSweepChart(canvas, sweep, scenario, protocols) {
  if (sweep.points.length === 1) {
    return buildLatencyChart(canvas, sweep, protocols, scenario);
  }
  return buildTrendLineChart(canvas, sweep, protocols, scenario);
}

// ---- CDF chart (single-point sweep) ---------------------------------
//
// Each successful sim contributes 1/Iterations to the cumulative success
// fraction at its decision time. The line steps up at every sample's
// x-coordinate and plateaus at the right edge — protocols that don't
// decide every time leave the plateau below 1.0.

function cdfPoints(sortedSamples, iterations) {
  if (!iterations) return [];
  const pts = [{ x: 0, y: 0 }];
  for (let i = 0; i < sortedSamples.length; i++) {
    const x = sortedSamples[i];
    const y = (i + 1) / iterations;
    // Collapse runs at the same integer ms (common at the P99 tail
    // where many samples cluster on the same millisecond after the
    // Go-side int(v+0.5) rounding) into a single point at the run's
    // top y. Without this, Chart.js's nearest-by-x lookup at the run's
    // x finds multiple points → duplicate tooltip rows; hovering on
    // the bottom edge of the resulting visual step also reads the
    // pre-step y instead of the cumulative value at that x.
    const last = pts[pts.length - 1];
    if (last.x === x) {
      last.y = y;
    } else {
      pts.push({ x, y });
    }
  }
  return pts;
}

function cdfChartData(sweep, protocols, scenario) {
  const point = sweep.points[0];
  return {
    datasets: protocols.map((p) => {
      const cell = findCell(point, scenario.name, p);
      const samples = (cell && cell.decisionTimes) || [];
      const iters = cell ? cell.iterations : 0;
      const pts = cdfPoints(samples, iters);
      // Mark the line's terminator (the protocol's last sample) with a
      // square; earlier points hidden. The legend chip already carries
      // the success-rate signal, so the line stops at its real end
      // rather than getting prolonged to the slot cutoff.
      const lastIdx = samples.length > 0 ? pts.length - 1 : -1;
      const radii = pts.map((_, i) => (i === lastIdx ? 7 : 0));
      const styles = pts.map((_, i) => (i === lastIdx ? 'rect' : 'circle'));
      return {
        label: p,
        borderColor: protocolColor(p),
        backgroundColor: protocolColor(p),
        // Step-before: horizontal at y_i until the next sample's x, then
        // vertical jump up at x_{i+1}. This is the left-continuous CDF
        // shape — line stays at the bottom until each new sample lifts
        // it. (Chart.js's `stepped: 'after'` is the right-continuous
        // version, which draws horizontal at the *new* y, putting the
        // line at the top for a single-jump CDF like 0→1 at x=3500.)
        stepped: 'before',
        pointRadius: radii,
        pointStyle: styles,
        pointHoverRadius: 7,
        borderWidth: 2,
        data: pts,
      };
    }),
  };
}

function buildLatencyChart(canvas, sweep, protocols, scenario) {
  return new Chart(canvas, {
    type: 'line',
    data: cdfChartData(sweep, protocols, scenario),
    plugins: [cdfZonesPlugin],
    options: {
      responsive: true,
      maintainAspectRatio: false,
      interaction: { mode: 'nearest', intersect: false, axis: 'x' },
      scales: {
        x: {
          type: 'linear',
          title: { display: true, text: 'decision time (ms)' },
          min: 0,
          max: SLOT_END_MS,
          grid: { display: false },
          ticks: { padding: 4 },
        },
        y: {
          title: { display: true, text: 'cumulative success rate' },
          min: 0,
          max: 1,
          grid: { color: 'rgba(15, 23, 42, 0.06)' },
          ticks: {
            padding: 6,
            callback: (v) => `${Math.round(v * 100)}%`,
          },
        },
      },
      plugins: {
        legend: { display: false },
        tooltip: {
          callbacks: {
            title: (items) => (items[0] ? `${Math.round(items[0].parsed.x)} ms` : ''),
            label: (ctx) => {
              const pct = (ctx.parsed.y * 100).toFixed(1);
              return `${ctx.dataset.label}: ${pct}% finished`;
            },
          },
        },
      },
    },
  });
}

// ---- trend line chart (multi-point sweep) ---------------------------

function buildTrendLineChart(canvas, sweep, protocols, scenario) {
  return new Chart(canvas, {
    type: 'line',
    data: trendLineChartData(sweep, protocols, scenario),
    options: {
      responsive: true,
      maintainAspectRatio: false,
      interaction: { mode: 'nearest', intersect: false },
      scales: {
        x: {
          title: { display: true, text: sweep.axisLabel || '' },
          grid: { display: false },
          ticks: { padding: 4 },
        },
        y: {
          title: { display: true, text: 'p99 decision time (ms)' },
          grid: { color: 'rgba(15, 23, 42, 0.06)' },
          ticks: { padding: 6 },
        },
      },
      plugins: {
        legend: { display: false },
        tooltip: {
          callbacks: {
            title: (items) =>
              items[0] ? `${sweep.axisLabel || 'point'}: ${items[0].label}` : '',
            label: (ctx) => `${ctx.dataset.label}: p99 ${Math.round(ctx.parsed.y)} ms`,
          },
        },
      },
    },
  });
}

function trendLineChartData(sweep, protocols, scenario) {
  return {
    labels: sweep.points.map((pt) => pt.label),
    datasets: protocols.map((p) => {
      const data = sweep.points.map((pt) => {
        const cell = findCell(pt, scenario.name, p);
        if (!cell || cell.iterations === 0 || !cell.decisionTime) return null;
        return cell.decisionTime.p99;
      });
      return {
        label: p,
        borderColor: protocolColor(p),
        backgroundColor: protocolColor(p),
        pointStyle: protocolPointStyle(p),
        spanGaps: true,
        fill: false,
        tension: 0.15,
        borderDash: protocolDash(p),
        data,
      };
    }),
  };
}

// ---- helpers ---------------------------------------------------------

// h(tag, attrs, ...children) — small DOM builder. attrs are setAttribute'd
// (except 'class', which sets className). Children may be strings, DOM
// nodes, or null/undefined (skipped).
function h(tag, attrs, ...children) {
  const el = document.createElement(tag);
  if (attrs) {
    Object.entries(attrs).forEach(([k, v]) => {
      if (k === 'class') el.className = v;
      else el.setAttribute(k, v);
    });
  }
  children.flat().forEach((c) => {
    if (c == null) return;
    if (typeof c === 'string' || typeof c === 'number') {
      el.appendChild(document.createTextNode(String(c)));
    } else {
      el.appendChild(c);
    }
  });
  return el;
}

function findCell(point, scenarioName, protocolName) {
  return point.cells.find((c) => c.scenario === scenarioName && c.protocol === protocolName) || null;
}

function protocolColor(name) {
  return PROTOCOL_COLORS[name] || '#888';
}

function protocolDash(name) {
  return name === 'OBFT' ? [] : [6, 4];
}

function protocolPointStyle(name) {
  switch (name) {
    case 'OBFT':
      return 'circle';
    case 'QBFT':
      return 'triangle';
    default:
      return 'rect';
  }
}

function escapeHtml(s) {
  return String(s).replace(/[&<>"']/g, (ch) => ({
    '&': '&amp;',
    '<': '&lt;',
    '>': '&gt;',
    '"': '&quot;',
    "'": '&#39;',
  })[ch]);
}

// formatDescription HTML-escapes the input, then wraps three families of
// tokens in <strong> for visual emphasis: set literals like {4, 7, 10},
// parameter assignments like n=4 / BTT=200ms, and known network-model
// names. Result is an HTML fragment suitable for innerHTML.
function formatDescription(text) {
  const networkModels = '(?:ConstantDelay|LogNormalDelay|LossyNetwork|PerReceiverDelay|CorrelatedLinkDelay|JitteredDelay)';
  let out = escapeHtml(text);
  const patterns = [
    /\{[^}]+\}/g,
    /\b[A-Za-z][A-Za-z_0-9]*=[A-Za-z0-9./_]+(?:ms|s)?\b/g,
    new RegExp('\\b' + networkModels + '\\b', 'g'),
  ];
  patterns.forEach((re) => {
    out = out.replace(re, (m) => `<strong>${m}</strong>`);
  });
  return out;
}
